func detectedAs(m store.Media) string {
	g := guessFor(m)
	if g.IsEpisode() {
		return g.Show + " · S" + strconv.Itoa(m.Season) + "E" + strconv.Itoa(m.Episode) + " · " + m.Title
	}
	if m.Year != "" {
		return m.Title + " (" + m.Year + ")"
	}
	return m.Title
}

