func techSummary(m store.Media) string {
	s := m.VideoCodec
	if m.AudioCodec != "" {
		s += " / " + m.AudioCodec
	}
	if m.Duration > 0 {
		s += " · " + minutes(m.Duration)
	}
	s += " · " + strconv.FormatFloat(float64(m.Size)/(1<<30), 'f', 2, 64) + " GB"
	return s
}

